var FINANCE_MODULE=[
{id:'fin_01',level:'Finance',title:'Основы финансов',theory:'**4 столпа:**\n1. Доход\n2. Расходы\n3. Сбережения\n4. Инвестиции\n\n**Правило 50/30/20:**\n• 50% нужды\n• 30% желания\n• 20% сбережения\n\n**Подушка:** 3-6 месяцев расходов.',practice:'Посчитай свой бюджет по 50/30/20. Запиши.',memory:'50/30/20 = карта.',keywords:'finance basics'},
{id:'fin_02',level:'Finance',title:'Учёт расходов',theory:'**Методы:**\n• Приложения (CoinKeeper, Monefy)\n• Таблица Excel\n• Конверты (наличные)\n• Правило 24 часов\n\n**Правило:** записывай каждую трату.',practice:'Записывай все расходы 7 дней. Проанализируй.',memory:'Учёт = контроль.',keywords:'budgeting'},
{id:'fin_03',level:'Finance',title:'Долги',theory:'**2 метода:**\n• Снежный ком (мелкий долг первый)\n• Лавина (высокий % первый)\n\n**Правило:** минимум по всем, максимум по одному.\n\n**Рефинансирование:** снизить %.',practice:'Список долгов. Выбери метод. Составь план.',memory:'Долг = минус. Убирай.',keywords:'debt'},
{id:'fin_04',level:'Finance',title:'Инвестиции',theory:'**Принципы:**\n• Долгосрочно (10+ лет)\n• Диверсификация\n• Индексные фонды\n• Регулярно (DCA)\n• Не пытайся угадать рынок\n\n**Сложный процент:** 10% годовых → ×2 за 7 лет.',practice:'Изучи 3 индексных фонда. Посчитай сложный процент.',memory:'Инвестиции = время + дисциплина.',keywords:'investing'},
{id:'fin_05',level:'Finance',title:'Финансовая независимость (FIRE)',theory:'**FIRE = Financial Independence, Retire Early.**\n\n**Формула:**\n• Норма сбережений 50%+\n• 25× годовых расходов\n• 4% правило вывода\n\n**Пример:** расходы 50к/мес → нужно 15 млн.',practice:'Посчитай свой FIRE-число. Составь план.',memory:'FIRE = свобода.',keywords:'FIRE'},
{id:'fin_06',level:'Finance',title:'Доход',theory:'**Источники:**\n• Основная работа\n• Фриланс\n• Пассивный доход\n• Инвестиции\n• Бизнес\n\n**Правило:** 3+ источника дохода.',practice:'Найди 2 идеи доп. дохода. Составь план.',memory:'Доход = множественный.',keywords:'income'},
{id:'fin_07',level:'Finance',title:'Налоги и вычеты',theory:'**В РФ:**\n• НДФЛ 13-15%\n• ИИС (инвестиционный)\n• Вычеты: обучение, лечение, имущество\n• Самозанятость 4-6%\n\n**Правило:** используй вычеты — верни до 15%.',practice:'Проверь, какие вычеты тебе доступны.',memory:'Налоги = законно оптимизируй.',keywords:'taxes'},
{id:'fin_08',level:'Finance',title:'Финансовые цели',theory:'**SMART-цели:**\n• Specific\n• Measurable\n• Achievable\n• Relevant\n• Time-bound\n\n**Пример:** "Накопить 500к за 12 месяцев, откладывая 42к/мес."',practice:'Поставь 3 финансовые цели по SMART.',memory:'Цель = цифра + срок.',keywords:'goals'},
{id:'fin_09',level:'Finance',title:'Психология денег',theory:'**Ловушки:**\n• Импульсивные покупки\n• Lifestyle inflation\n• FOMO\n• Эмоциональные траты\n\n**Правило 24 часов:** подожди перед покупкой.',practice:'Применяй правило 24 часов неделю. Запиши экономию.',memory:'Деньги = эмоции. Управляй.',keywords:'money psychology'},
{id:'fin_10',level:'Finance',title:'Итог: финансовая система',theory:'**Твоя система:**\n1. Учёт расходов\n2. Бюджет 50/30/20\n3. Подушка 3-6 мес\n4. Долги по лавине\n5. Инвестиции 20%\n6. 3+ источника дохода\n7. Вычеты\n\n**Через год:** +30% к капиталу.',practice:'Составь личный финплан на год.',memory:'Система > удача.',keywords:'finance system'}
];

