var NEURO_MODULE=[
{id:'neuro_01',level:'Neuro',title:'Как учится мозг',theory:'**Нейропластичность:** мозг меняется всю жизнь.\n\n**Синапсы:** связь между нейронами. Чем чаще — тем сильнее.\n\n**Правило Хебба:** "Fire together, wire together."\n\n**Миелин:** ускоряет сигнал в 100 раз.',practice:'Учи 1 навык 30 дней по 15 мин. Отслеживай.',memory:'Мозг = мышца. Тренируй.',keywords:'neuroplasticity'},
{id:'neuro_02',level:'Neuro',title:'Дофамин и мотивация',theory:'**Дофамин = предвкушение, не награда.**\n\n**Проблема:** соцсети, игры, сахар → дофаминовые ямы.\n\n**Решение:**\n• Дофаминовое голодание\n• Скука полезна\n• Награда после усилия\n• Утро без телефона',practice:'Проведи дофаминовое голодание 4 часа. Запиши эффект.',memory:'Дофамин = топливо. Управляй.',keywords:'dopamine'},
{id:'neuro_03',level:'Neuro',title:'Сон и обучение',theory:'**Фазы сна:**\n• NREM (медленный) — факты\n• REM — эмоции, креатив\n\n**Консолидация:** во сне мозг переносит из краткосрочной в долгосрочную.\n\n**Правило:** 7-9 часов. Учи перед сном.',practice:'Учи 10 слов перед сном. Проверь утром.',memory:'Сон = обучение.',keywords:'sleep learning'},
{id:'neuro_04',level:'Neuro',title:'Стресс и обучение',theory:'**Оптимальный стресс:**\n• Слишком мало → скука\n• Слишком много → блок\n• Средний → поток\n\n**Кортизол:** хронический стресс убивает нейроны гиппокампа.\n\n**Решение:** спорт, медитация, сон, природа.',practice:'Найди свой оптимальный уровень стресса для учёбы.',memory:'Стресс = дозируй.',keywords:'stress learning'},
{id:'neuro_05',level:'Neuro',title:'Питание для мозга',theory:'**Топ-продукты:**\n• Omega-3 (рыба, орехи)\n• Ягоды (антиоксиданты)\n• Тёмный шоколад 70%+\n• Зелёный чай\n• Яйца (холин)\n• Куркума\n\n**Избегать:** сахар, трансжиры, алкоголь.',practice:'Добавь 3 продукта в рацион на неделю.',memory:'Мозг = 60% жира. Корми правильно.',keywords:'brain nutrition'},
{id:'neuro_06',level:'Neuro',title:'Физические упражнения',theory:'**BDNF (brain-derived neurotrophic factor):** "удобрение для мозга".\n\n**Эффект:**\n• Аэробные 30 мин → +20% памяти\n• Силовые → +исполнительные функции\n• Прогулка → +креативность\n\n**Правило:** 150 мин кардио + 2 силовые в неделю.',practice:'30 мин кардио перед учёбой. Запиши эффект.',memory:'Движение = мозг.',keywords:'exercise brain'},
{id:'neuro_07',level:'Neuro',title:'Медитация и мозг',theory:'**Эффекты:**\n• Утолщение префронтальной коры\n• Уменьшение миндалины\n• +внимание, +эмпатия\n• -тревога, -стресс\n\n**Доза:** 10-20 мин/день, 8 недель.',practice:'Медитируй 10 мин/день 8 недель. Замерь изменения.',memory:'Медитация = фитнес для мозга.',keywords:'meditation'},
{id:'neuro_08',level:'Neuro',title:'Внимание и фокус',theory:'**Типы внимания:**\n• Фокус (1 задача)\n• Рассеянное (творчество)\n• Переключение (дорого!)\n\n**Стоимость переключения:** 23 минуты на возврат.\n\n**Правило:** одна задача за раз.',practice:'Работай 90 мин с одной задачей. Без телефона.',memory:'Фокус = валюта XXI века.',keywords:'attention focus'},
{id:'neuro_09',level:'Neuro',title:'Креативность',theory:'**Default Mode Network:** активна в покое.\n\n**Техники:**\n• Прогулка\n• Душ\n• Скука\n• Смена обстановки\n• Медитация\n\n**Правило:** креатив требует простоя.',practice:'Прогулка 30 мин без телефона. Запиши идеи.',memory:'Креатив = покой + опыт.',keywords:'creativity'},
{id:'neuro_10',level:'Neuro',title:'Итог: нейро-система',theory:'**Оптимизация:**\n1. Сон 7-9 ч\n2. Спорт 150 мин\n3. Медитация 10 мин\n4. Питание для мозга\n5. Фокус 90 мин\n6. Дофамин-контроль\n7. Стресс-менеджмент\n\n**Через 3 месяца:** мозг работает в 2 раза эффективнее.',practice:'Составь нейро-расписание на неделю.',memory:'Мозг = орган. Ухаживай.',keywords:'neuro system'}
];

